require_once dirname(__DIR__).'/app/bootstrap.php';header('X-Robots-Tag: noindex, nofollow, noarchive');require_login(current_request_target());header('Cache-Control: private, no-store, max-age=0');$category=trim((string)($_GET['category']??''));$params=[];$where="status='published'";if($category!==''&&in_array($category,categories(),true)){$where.=' AND category=:c';$params[':c']=$category;}$s=db()->prepare("SELECT id,name,slug,category,location,address,latitude,longitude,image_path,image_url FROM listings WHERE $where ORDER BY featured DESC,name");$s->execute($params);$rows=$s->fetchAll();$mapped=array_values(array_filter($rows,fn($r)=>$r['latitude']!==null&&$r['longitude']!==null));$pageTitle='Explore the map | '.setting('site_name','MetroGuide');$pageDescription='Explore local places on an interactive map with clustered pins and category filters.';include __DIR__.'/includes/header.php';?>
<main id="main" class="container map-page"><div class="page-intro"><span class="eyebrow">EXPLORE NEARBY</span><h1>Find your way around.</h1><p>Filter the directory by category. Map pins cluster together at wider zoom levels; choose a pin to open its business profile.</p></div><form class="lg3-filter-form" method="get"><label>Category<select name="category"><option value="">All categories</option><?php foreach(categories() as $c): ?><option value="<?= h($c) ?>" <?= $category===$c?'selected':'' ?>><?= h($c) ?></option><?php endforeach; ?></select></label><button class="button button-primary">Apply filter</button></form><div class="map-layout"><section class="map-canvas-wrap"><div id="localGuideMap" aria-label="Map of local businesses"></div><div class="map-attribution-note">Map data © OpenStreetMap contributors. <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">Attribution</a></div></section><aside class="map-results"><h2>Directory places</h2><p><?= count($rows) ?> published listings · <?= count($mapped) ?> with map pins</p><?php foreach($rows as $r): ?><a class="map-result" href="<?= app_path('index.php?listing='.rawurlencode($r['slug'])) ?>"><strong><?= h($r['name']) ?></strong><small><?= h($r['category']) ?> · <?= h($r['location']) ?></small><?php if($r['latitude']!==null): ?><span><i class="fa-solid fa-location-dot"></i> Pinned on map</span><?php else: ?><span class="muted">Map coordinates not added yet</span><?php endif; ?></a><?php endforeach; ?></aside></div><?php if(!$mapped): ?><div class="alert alert-warning">No listings have coordinates yet. Add latitude and longitude in Admin → Listings to show map pins.</div><?php endif; ?></main>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin=""><link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.css"><link rel="stylesheet" href="https://unpkg.com/leaflet.markercluster@1.5.3/dist/MarkerCluster.Default.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script><script src="https://unpkg.com/leaflet.markercluster@1.5.3/dist/leaflet.markercluster.js"></script><script>window.LOCAL_GUIDE_MAP_ITEMS=<?= json_encode(array_map(fn($r)=>['name'=>$r['name'],'lat'=>(float)$r['latitude'],'lng'=>(float)$r['longitude'],'url'=>app_path('index.php?listing='.rawurlencode($r['slug'])),'category'=>$r['category']],$mapped),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;</script><script src="<?= app_path('assets/js/map.js') ?>" defer></script><?php include __DIR__.'/includes/footer.php';?>
